DO $body$ DECLARE def text;BEGIN
SELECT pg_get_functiondef('public.bani_people_execute(uuid,uuid,text)'::regprocedure) INTO def;
def:=replace(def,'SECURITY INVOKER','SECURITY DEFINER');
def:=replace(def,$s$r:=public.bani_people_claim$s$, $s$IF auth.uid() IS NULL OR NOT public.people_access(t,auth.uid()) THEN RAISE EXCEPTION 'People access required';END IF; r:=public.bani_people_claim$s$);
def:=replace(def,$s$h.approval_status='approved' OR h.accrual_journal_entry_id IS NOT NULL OR h.payment_status='paid'$s$, $s$h.accrual_journal_entry_id IS NOT NULL OR h.payment_status='paid' OR EXISTS(SELECT 1 FROM public.hr_payroll_months pm WHERE pm.tenant_id=h.tenant_id AND pm.year=h.year AND pm.month=h.month AND pm.status='approved')$s$);
def:=replace(def,$s$start_day:=(p->>'date_from')::date;end_day:=(p->>'date_to')::date;$s$, $s$start_day:=(p->>'date_from')::date;end_day:=(p->>'date_to')::date; IF decision='confirm' AND NULLIF(p->>'request_id','') IS NOT NULL THEN SELECT to_jsonb(l) INTO old FROM public.hr_leave_requests l WHERE l.id=(p->>'request_id')::uuid AND l.tenant_id=t AND l.employee_id=e FOR UPDATE; IF old IS DISTINCT FROM (SELECT value FROM jsonb_array_elements(p->'requests_before') WHERE value->>'id'=p->>'request_id') THEN RAISE EXCEPTION 'Leave request changed; review a fresh draft';END IF;END IF;$s$);
def:=replace(def,$s$IF NOT public.rota_manager(t,v,auth.uid()) THEN RAISE EXCEPTION 'Rota manager access required';END IF;$s$, $s$IF NOT public.rota_manager(t,v,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'rota')::boolean THEN RAISE EXCEPTION 'Rota manager access required';END IF; IF EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p->'before','[]')||COALESCE(p->'changes','[]')) x WHERE x ? 'employee_id' AND NOT public.people_person_access(t,(x->>'employee_id')::uuid,auth.uid())) THEN RAISE EXCEPTION 'Person access required';END IF;$s$);
def:=replace(def,$s$IF NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,e,auth.uid()) THEN RAISE EXCEPTION 'Leave manager access required';END IF;$s$, $s$IF NOT public.rota_manager(t,v,auth.uid()) OR NOT public.people_person_access(t,e,auth.uid()) OR NOT (public.people_effective_settings(t,v)->>'leave_requests')::boolean THEN RAISE EXCEPTION 'Leave manager access required';END IF;$s$);
EXECUTE def;END $body$;
REVOKE ALL ON FUNCTION public.bani_people_claim(uuid,uuid,text) FROM authenticated;
REVOKE ALL ON FUNCTION public.bani_people_finish(uuid,uuid,text,jsonb,jsonb) FROM authenticated;
COMMENT ON FUNCTION public.bani_people_execute(uuid,uuid,text) IS 'Only public card executor: authenticated ownership, row lock, existing People RPC authorization and explicit person/venue checks for compensating undo. Internal claim/finish have no API grants.';